<template>
  <div class="profile">
    <ProfileHeaderModeration
      title="Заявка на размещение объявления"
      :uniqueCode="publication?.id"
      :phone="publication?.phone || '+7 (000) 000-00-00'"
      :address="
        publication?.ads_parameter?.place_inspection ||
        'Ростовская область; Ростов-на-Дону; Ворошиловский р-н'
      "
      :date="publication?.updated_at"
      :moderator="publication?.ads_parameter?.username"
      :backIcon="backIcon"
      :goBack="goBack"
    />

    <!-- Скроллируемая часть -->
    <div class="profile__wrapper">
      <div class="violation-form">
        <h3 class="violation-form__title">
          Выберите контент, нарушающий правила сервиса и укажите причину:
        </h3>

        <div
          v-for="(item, key) in violations"
          :key="key"
          class="violation-block"
        >
          <div class="violation-block__info">
            <CheckboxUI v-model="item.enabled" />
            <p class="violation-block__title">{{ item.label }}</p>
          </div>
          <p class="violation-block__text">{{ item.content }}</p>
          <div class="violation-block__dropdown" v-if="item.enabled">
            <AdsDropdown
              :options="dropdownOptions"
              placeholder="Выберите причину"
              @updateSort="(val) => (item.reason = val)"
            />
          </div>
        </div>

        <div v-if="photosWithViolations?.label" class="divider"></div>

        <div class="photo-grid">
          <div
            v-for="photo in photosWithViolations"
            :key="photo.id"
            class="photo-block"
          >
            <img :src="photo.url" class="photo-block__img" />
            <div class="photo-block__checkbox">
              <CheckboxUI v-model="photo.enabled" />
            </div>
            <div class="photo-block__dropdown" v-if="photo.enabled">
              <AdsDropdown
                :options="dropdownOptions"
                placeholder="Выберите причину"
                @updateSort="(val) => (photo.reason = val)"
              />
            </div>
          </div>
        </div>
      </div>
    </div>

    <!-- Кнопки снизу вне скролла -->
    <div class="divider"></div>
    <div class="violation-form__actions">
      <button @click="approvePublication" class="btn approve">Разрешить</button>
      <button @click="rejectPublication" class="btn reject">Отклонить</button>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { getCarById, updateCarAd } from '@/services/apiClient';
import { getImageUrl } from '@/services/imageUtils';
import backIcon from '@/assets/icons/back-wide.svg';

import ProfileHeaderModeration from '@/components/UI/CustomProfileHeaderModeration.vue';
import CheckboxUI from '@/components/UI/CheckboxUINEW.vue';
import AdsDropdown from '@/components/AdsDropdown.vue';

const route = useRoute();
const router = useRouter();
const publication = ref(null);
const loading = ref(true);

const formattedAutoTitle = computed(() => {
  const autoSpecs = publication.value?.auto_technical_specifications?.[0];
  return `${autoSpecs?.brand?.title} ${autoSpecs?.model?.title} ${autoSpecs?.year_release?.title}`;
});

const violations = ref({
  title: {
    label: 'Заголовок',
    enabled: false,
    reason: null,
    get content() {
      return formattedAutoTitle.value || 'НЕ указано';
    },
  },
  description: {
    label: 'Описание',
    enabled: false,
    reason: null,
    get content() {
      return publication.value?.ads_parameter?.ads_description || 'НЕ указано';
    },
  },
});

const dropdownOptions = [
  { label: 'Нарушение законодательства (П. 2)', value: 'law_violation' },
  {
    label: 'Нарушение правил сервиса (П. 3)',
    value: 'service_rules_violation',
  },
  { label: 'Грубая лексика (П. 4)', value: 'offensive_language' },
  { label: 'Недостоверные данные (П. 5)', value: 'false_information' },
  { label: 'Мошенничество (П. 6)', value: 'fraud' },
  { label: 'Порнография (П. 7)', value: 'pornography' },
  { label: 'Другое', value: 'other' },
];

const photosWithViolations = ref([]);

const collectAdminComment = () => {
  const fieldsComment = {};

  // Нарушения по заголовку / описанию
  Object.entries(violations.value).forEach(([key, item]) => {
    if (item.enabled && item.reason) {
      fieldsComment[key] = item.reason;
    }
  });

  // Нарушения по фото
  photosWithViolations.value.forEach((photo) => {
    if (photo.enabled && photo.reason) {
      fieldsComment[`photo_${photo.id}`] = photo.reason;
    }
  });

  return fieldsComment;
};

const approvePublication = async () => {
  const formData = {
    is_draft: 0,
    is_cancelled: 0,
    is_finished: 1,
  };
  // нужен ли этот лог в проекте
  console.log('APPROVED DATA:', formData);
  await updateCarAd(route.params.id, formData);
};

const rejectPublication = async () => {
  const formData = {
    is_draft: 0,
    is_cancelled: 1,
    is_finished: 1,
    admin_comment: {
      fields_comment: collectAdminComment(),
    },
  };
  // нужен ли этот лог в проекте
  console.log('REJECTED DATA:', formData);
  await updateCarAd(route.params.id, formData);
};

const fetchPublicationData = async () => {
  try {
    const response = await getCarById(route.params.id);
    publication.value = response;

    photosWithViolations.value = (response?.photos || []).map((photo) => ({
      id: photo.id,
      title: photo.title,
      url: getImageUrl(photo.arr_title_size?.default) || '',
      enabled: false,
      reason: null,
    }));
  } catch (error) {
    console.error('Ошибка при получении данных объявления:', error);
    publication.value = null;
  } finally {
    loading.value = false;
  }
};

const goBack = () => {
  router.back();
};

onMounted(fetchPublicationData);
</script>

